using System.Data;
using CargoWise.RefDbRepo.Common.DbUpgrade;

namespace CargoWise.RefDbRepo.Service.UpgradeManagerRunner
{
	public class DataFixIncorrectTimezoneToYear : DataTransformation, IDataTransformationTask
	{
		public DataFixIncorrectTimezoneToYear(int version) : base(version)
		{
		}

		[System.Diagnostics.CodeAnalysis.SuppressMessage("Microsoft.Security", "CA2100:ReviewSqlQueriesForSecurityVulnerabilities")]
		public void Run(IDbTransaction trans)
		{
			var sql = @"
Update tzr set tzr.R4_ToYear = 2008
from RefTimeZoneSet tzs
join RefTimeZone tz on tz.R2_R3_TimeZoneSet = tzs.R3_PK
join RefTimeZoneRule tzr on tzr.R4_R2 = tz.R2_PK
where tzs.R3_TimeZoneSetName = 'Africa/Cairo'
and tzr.R4_FromYear = 2000
and tzr.R4_StartOrEndRule = 'STA'

Update tzr set tzr.R4_ToYear = 2014
from RefTimeZoneSet tzs
join RefTimeZone tz on tz.R2_R3_TimeZoneSet = tzs.R3_PK
join RefTimeZoneRule tzr on tzr.R4_R2 = tz.R2_PK
where tzs.R3_TimeZoneSetName = 'Africa/Cairo'
and tzr.R4_FromYear = 2014
and tzr.R4_StartOrEndRule = 'STA'

Update tzr set tzr.R4_ToYear = 2009
from RefTimeZoneSet tzs
join RefTimeZone tz on tz.R2_R3_TimeZoneSet = tzs.R3_PK
join RefTimeZoneRule tzr on tzr.R4_R2 = tz.R2_PK
where tzs.R3_TimeZoneSetName = 'Africa/Cairo'
and tzr.R4_FromYear = 2008
and tzr.R4_StartOrEndRule = 'END'

Update tzr set tzr.R4_ToYear = 2010
from RefTimeZoneSet tzs
join RefTimeZone tz on tz.R2_R3_TimeZoneSet = tzs.R3_PK
join RefTimeZoneRule tzr on tzr.R4_R2 = tz.R2_PK
where tzs.R3_TimeZoneSetName = 'Africa/Cairo'
and tzr.R4_FromYear = 2010
and tzr.R4_StartOrEndRule = 'END'

If not exists (select tzr.R4_PK from RefTimeZoneSet tzs
join RefTimeZone tz on tz.R2_R3_TimeZoneSet = tzs.R3_PK
join RefTimeZoneRule tzr on tzr.R4_R2 = tz.R2_PK
where tzs.R3_TimeZoneSetName = 'Africa/Cairo'
and tzr.R4_FromYear = 2014
and tzr.R4_ToYear = 2014
and tzr.R4_StartOrEndRule = 'END')
Begin
	Insert into RefTimeZoneRule
	(R4_PK,R4_FromYear,R4_ToYear,R4_StartOrEndRule,R4_DaylightSavingDayWeekDate,R4_DaylightSavingDate
	,R4_DaylightSavingDayCount,R4_DaylightSavingDayName,R4_DaylightSavingMonth,R4_TypeOfTime,R4_R2)
	select top 1 newid(),2014,2014,'END','MON','1999-12-31 23:00:00',5
	,'FRI','SEP','LOC',[R4_R2]
	from RefTimeZoneSet tzs
	join RefTimeZone tz on tz.R2_R3_TimeZoneSet = tzs.R3_PK
	join RefTimeZoneRule tzr on tzr.R4_R2 = tz.R2_PK
	where tzs.R3_TimeZoneSetName = 'Africa/Cairo'
	and tzr.R4_FromYear = 2010
	and tzr.R4_StartOrEndRule = 'END'
END

Update tzr set tzr.R4_ToYear = 2017
from RefTimeZoneSet tzs
join RefTimeZone tz on tz.R2_R3_TimeZoneSet = tzs.R3_PK
join RefTimeZoneRule tzr on tzr.R4_R2 = tz.R2_PK
where tzs.R3_TimeZoneSetName = 'america/sao_paulo'
and tzr.R4_FromYear = 2008
and tzr.R4_StartOrEndRule = 'STA'

Update tzr set tzr.R4_ToYear = 2019
from RefTimeZoneSet tzs
join RefTimeZone tz on tz.R2_R3_TimeZoneSet = tzs.R3_PK
join RefTimeZoneRule tzr on tzr.R4_R2 = tz.R2_PK
where tzs.R3_TimeZoneSetName = 'america/sao_paulo'
and tzr.R4_FromYear = 2018
and tzr.R4_StartOrEndRule = 'STA'

Update tzr set tzr.R4_ToYear = 2019
from RefTimeZoneSet tzs
join RefTimeZone tz on tz.R2_R3_TimeZoneSet = tzs.R3_PK
join RefTimeZoneRule tzr on tzr.R4_R2 = tz.R2_PK
where tzs.R3_TimeZoneSetName = 'america/sao_paulo'
and tzr.R4_FromYear = 2016
and tzr.R4_StartOrEndRule = 'END'

Delete from tzr
from RefTimeZoneSet tzs
join RefTimeZone tz on tz.R2_R3_TimeZoneSet = R3_PK
join RefTimeZoneRule tzr on tzr.R4_R2 = R2_PK
where tzs.R3_TimeZoneSetName in ('America/Recife',
'Pacific/Fiji',
'Asia/Bishkek',
'America/Argentina/La_Rioja',
'Asia/Oral',
'Pacific/Apia',
'America/Argentina/Ushuaia',
